contracts/ETNReverseRegistrar.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "./ETNRegistry.sol";
import "./ETNPublicResolver.sol";

/**
 * @title ETNReverseRegistrar
 * @notice Allows any address to claim a reverse record so wallets can show
 *         "alice.etn" instead of "0xAbc…" in UIs.
 *
 * Reverse nodes live under the special TLD:
 *   <addr-hex-lowercase>.addr.reverse
 *
 * Compatible with ENS reverse resolution: tools that know ENS reverse lookup
 * will work as-is once pointed at this registrar and the public resolver.
 */
contract ETNReverseRegistrar {

    // ─────────────────────────────────────────────
    //  Constants
    // ─────────────────────────────────────────────

    /// namehash("addr.reverse")
    bytes32 public constant ADDR_REVERSE_NODE =
        0x91d1777781884d03a0022c3ff27df9e8a76d78dfcec09b2e21c7d84cfb6f2ba4;

    // ─────────────────────────────────────────────
    //  State
    // ─────────────────────────────────────────────

    ETNRegistry       public immutable registry;
    ETNPublicResolver public           defaultResolver;

    // ─────────────────────────────────────────────
    //  Events
    // ─────────────────────────────────────────────

    event ReverseClaimed(address indexed addr, bytes32 indexed node);

    // ─────────────────────────────────────────────
    //  Constructor
    // ─────────────────────────────────────────────

    constructor(address _registry, address _resolver) {
        registry        = ETNRegistry(_registry);
        defaultResolver = ETNPublicResolver(_resolver);
    }

    // ─────────────────────────────────────────────
    //  Claim
    // ─────────────────────────────────────────────

    /**
     * @notice Claim a reverse record for msg.sender and set the forward name.
     * @param forwardName  The .etn name to associate (e.g. "alice.etn")
     */
    function setName(string calldata forwardName) external returns (bytes32) {
        bytes32 node = claimWithResolver(msg.sender, address(defaultResolver));
        defaultResolver.setName(node, forwardName);
        return node;
    }

    /**
     * @notice Claim the reverse node for `addr`, setting `resolver` as its resolver.
     *         Can only be called by `addr` itself.
     */
    function claimWithResolver(address addr, address resolver)
        public returns (bytes32 node)
    {
        require(
            addr == msg.sender,
            "ETNReverseRegistrar: only callable by address owner"
        );

        bytes32 labelHash = keccak256(bytes(_toHexString(addr)));
        node = keccak256(abi.encodePacked(ADDR_REVERSE_NODE, labelHash));

        registry.setSubnodeOwner(ADDR_REVERSE_NODE, labelHash, addr);
        if (resolver != address(0)) {
            registry.setResolver(node, resolver);
        }

        emit ReverseClaimed(addr, node);
    }

    /**
     * @notice Look up the reverse node for an address (read-only).
     */
    function node(address addr) public pure returns (bytes32) {
        bytes32 labelHash = keccak256(bytes(_toHexString(addr)));
        return keccak256(abi.encodePacked(ADDR_REVERSE_NODE, labelHash));
    }

    // ─────────────────────────────────────────────
    //  Internal — address to lowercase hex string
    // ─────────────────────────────────────────────

    function _toHexString(address addr) internal pure returns (string memory) {
        bytes memory alphabet = "0123456789abcdef";
        bytes memory result   = new bytes(40);
        uint160 value = uint160(addr);
        for (uint256 i = 40; i > 0; i--) {
            result[i - 1] = alphabet[value & 0xf];
            value >>= 4;
        }
        return string(result);
    }
}

contracts/ETNRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/**
 * @title ETNRegistry
 * @notice Central registry for all .etn and .project.etn names.
 *         Stores owner, resolver, and TTL for every registered node.
 *         Architecture mirrors ENS — a pure registry with no pricing logic.
 */
contract ETNRegistry {

    // ─────────────────────────────────────────────
    //  Structs & state
    // ─────────────────────────────────────────────

    struct Record {
        address owner;
        address resolver;
        uint64  ttl;
    }

    /// node (namehash) => Record
    mapping(bytes32 => Record) internal _records;

    /// node => (operator => approved)
    mapping(bytes32 => mapping(address => bool)) internal _operators;

    // ─────────────────────────────────────────────
    //  Events
    // ─────────────────────────────────────────────

    event NewOwner   (bytes32 indexed node, bytes32 indexed label, address owner);
    event Transfer   (bytes32 indexed node, address owner);
    event NewResolver(bytes32 indexed node, address resolver);
    event NewTTL     (bytes32 indexed node, uint64 ttl);
    event ApprovalForAll(address indexed owner, address indexed operator, bool approved);

    // ─────────────────────────────────────────────
    //  Modifiers
    // ─────────────────────────────────────────────

    modifier authorised(bytes32 node) {
        address owner = _records[node].owner;
        require(
            owner == msg.sender || _operators[node][msg.sender],
            "ETNRegistry: not authorised"
        );
        _;
    }

    // ─────────────────────────────────────────────
    //  Constructor — bootstrap root node
    // ─────────────────────────────────────────────

    constructor() {
        _records[0x0].owner = msg.sender;
    }

    // ─────────────────────────────────────────────
    //  Write functions
    // ─────────────────────────────────────────────

    /**
     * @notice Set a subnode owner. Called by the Registrar when minting a name.
     * @param node   Parent node  (e.g. namehash("etn"))
     * @param label  keccak256 of the label being registered (e.g. keccak256("alice"))
     * @param owner_ The new owner address
     */
    function setSubnodeOwner(
        bytes32 node,
        bytes32 label,
        address owner_
    ) external authorised(node) returns (bytes32 subnode) {
        subnode = keccak256(abi.encodePacked(node, label));
        _setOwner(subnode, owner_);
        emit NewOwner(node, label, owner_);
    }

    /**
     * @notice Set the full record for a node in one call.
     */
    function setRecord(
        bytes32 node,
        address owner_,
        address resolver_,
        uint64  ttl_
    ) external authorised(node) {
        _setOwner(node, owner_);
        _records[node].resolver = resolver_;
        _records[node].ttl      = ttl_;
        emit NewResolver(node, resolver_);
        emit NewTTL(node, ttl_);
    }

    function setSubnodeRecord(
        bytes32 node,
        bytes32 label,
        address owner_,
        address resolver_,
        uint64  ttl_
    ) external authorised(node) returns (bytes32 subnode) {
        subnode = keccak256(abi.encodePacked(node, label));
        _setOwner(subnode, owner_);
        _records[subnode].resolver = resolver_;
        _records[subnode].ttl      = ttl_;
        emit NewOwner(node, label, owner_);
        emit NewResolver(subnode, resolver_);
        emit NewTTL(subnode, ttl_);
    }

    function setOwner(bytes32 node, address owner_) external authorised(node) {
        _setOwner(node, owner_);
        emit Transfer(node, owner_);
    }

    function setResolver(bytes32 node, address resolver_) external authorised(node) {
        _records[node].resolver = resolver_;
        emit NewResolver(node, resolver_);
    }

    function setTTL(bytes32 node, uint64 ttl_) external authorised(node) {
        _records[node].ttl = ttl_;
        emit NewTTL(node, ttl_);
    }

    function setApprovalForAll(bytes32 node, address operator, bool approved) external {
        require(msg.sender == _records[node].owner, "ETNRegistry: not owner");
        _operators[node][operator] = approved;
        emit ApprovalForAll(msg.sender, operator, approved);
    }

    // ─────────────────────────────────────────────
    //  Read functions
    // ─────────────────────────────────────────────

    function owner   (bytes32 node) external view returns (address) { return _records[node].owner; }
    function resolver(bytes32 node) external view returns (address) { return _records[node].resolver; }
    function ttl     (bytes32 node) external view returns (uint64)  { return _records[node].ttl; }

    function recordExists(bytes32 node) external view returns (bool) {
        return _records[node].owner != address(0);
    }

    function isApprovedForAll(bytes32 node, address operator) external view returns (bool) {
        return _operators[node][operator];
    }

    // ─────────────────────────────────────────────
    //  Internal
    // ─────────────────────────────────────────────

    function _setOwner(bytes32 node, address owner_) internal {
        _records[node].owner = owner_;
    }
}

contracts/ETNPublicResolver.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "./ETNRegistry.sol";

/**
 * @title ETNPublicResolver
 * @notice Stores address, text, and content-hash records for .etn names.
 *         Mirrors the ENS PublicResolver interface so existing tooling works.
 *
 * Supported record types:
 *   addr(node)              — EVM address (chain 52014 by default)
 *   addr(node, coinType)    — multi-coin addresses (SLIP-0044)
 *   text(node, key)         — arbitrary key/value (avatar, url, email, …)
 *   contenthash(node)       — IPFS / Arweave / Swarm content hash
 *   name(node)              — canonical name (reverse records)
 */
contract ETNPublicResolver {

    // ─────────────────────────────────────────────
    //  State
    // ─────────────────────────────────────────────

    ETNRegistry public immutable registry;

    /// node → EVM address
    mapping(bytes32 => address) private _addresses;

    /// node → coinType → bytes address
    mapping(bytes32 => mapping(uint256 => bytes)) private _coinAddresses;

    /// node → key → value
    mapping(bytes32 => mapping(string => string)) private _texts;

    /// node → contenthash bytes
    mapping(bytes32 => bytes) private _contentHashes;

    /// node → canonical name
    mapping(bytes32 => string) private _names;

    // ─────────────────────────────────────────────
    //  Events
    // ─────────────────────────────────────────────

    event AddrChanged       (bytes32 indexed node, address addr);
    event AddressChanged    (bytes32 indexed node, uint256 coinType, bytes newAddress);
    event TextChanged       (bytes32 indexed node, string indexed key, string value);
    event ContenthashChanged(bytes32 indexed node, bytes hash);
    event NameChanged       (bytes32 indexed node, string name);

    // ─────────────────────────────────────────────
    //  Modifier
    // ─────────────────────────────────────────────

    modifier authorised(bytes32 node) {
        address nodeOwner = registry.owner(node);
        require(
            nodeOwner == msg.sender ||
            registry.isApprovedForAll(node, msg.sender),
            "ETNResolver: not authorised"
        );
        _;
    }

    // ─────────────────────────────────────────────
    //  Constructor
    // ─────────────────────────────────────────────

    constructor(address _registry) {
        registry = ETNRegistry(_registry);
    }

    // ─────────────────────────────────────────────
    //  Address records
    // ─────────────────────────────────────────────

    function setAddr(bytes32 node, address addr) external authorised(node) {
        _addresses[node] = addr;
        emit AddrChanged(node, addr);
    }

    function addr(bytes32 node) external view returns (address) {
        return _addresses[node];
    }

    function setAddr(bytes32 node, uint256 coinType, bytes calldata a)
        external authorised(node)
    {
        _coinAddresses[node][coinType] = a;
        emit AddressChanged(node, coinType, a);
    }

    function addr(bytes32 node, uint256 coinType)
        external view returns (bytes memory)
    {
        return _coinAddresses[node][coinType];
    }

    // ─────────────────────────────────────────────
    //  Text records
    // ─────────────────────────────────────────────

    function setText(bytes32 node, string calldata key, string calldata value)
        external authorised(node)
    {
        _texts[node][key] = value;
        emit TextChanged(node, key, value);
    }

    function text(bytes32 node, string calldata key)
        external view returns (string memory)
    {
        return _texts[node][key];
    }

    // ─────────────────────────────────────────────
    //  Content hash
    // ─────────────────────────────────────────────

    function setContenthash(bytes32 node, bytes calldata hash)
        external authorised(node)
    {
        _contentHashes[node] = hash;
        emit ContenthashChanged(node, hash);
    }

    function contenthash(bytes32 node) external view returns (bytes memory) {
        return _contentHashes[node];
    }

    // ─────────────────────────────────────────────
    //  Canonical name (reverse resolution)
    // ─────────────────────────────────────────────

    function setName(bytes32 node, string calldata _name)
        external authorised(node)
    {
        _names[node] = _name;
        emit NameChanged(node, _name);
    }

    function name(bytes32 node) external view returns (string memory) {
        return _names[node];
    }

    // ─────────────────────────────────────────────
    //  ERC-165 supportsInterface
    // ─────────────────────────────────────────────

    function supportsInterface(bytes4 interfaceID) external pure returns (bool) {
        return
            interfaceID == 0x01ffc9a7 || // ERC-165
            interfaceID == 0x3b3b57de || // addr(bytes32)
            interfaceID == 0xf1cb7e06 || // addr(bytes32,uint256)
            interfaceID == 0x59d1d43c || // text
            interfaceID == 0xbc1c58d1 || // contenthash
            interfaceID == 0x691f3431;   // name
    }
}

contracts/ETNNameHash.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/**
 * @title ETNNamehash
 * @notice Pure library implementing the ENS namehash algorithm (EIP-137).
 *
 * namehash("") = 0x000...000
 * namehash("etn") = keccak256(namehash("") ++ keccak256("etn"))
 * namehash("alice.etn") = keccak256(namehash("etn") ++ keccak256("alice"))
 *
 * Pre-computed roots for convenience:
 *   ETN_NODE   = namehash("etn")
 */
library ETNNamehash {

    bytes32 internal constant ETN_NODE =
        0x587d09fe5fa45354680537d38145a28b772971e0f293af3ee0c536fc919710fb;
        // keccak256(abi.encodePacked(bytes32(0), keccak256("etn")))

    /**
     * @notice Compute namehash for a single-label name under .etn
     *         e.g. label = keccak256("alice") → namehash("alice.etn")
     */
    function etnNode(bytes32 labelHash) internal pure returns (bytes32) {
        return keccak256(abi.encodePacked(ETN_NODE, labelHash));
    }

    /**
     * @notice Compute namehash for a two-label name under .etn
     *         e.g. project "defi", name "alice" → namehash("alice.defi.etn")
     */
    function projectNode(bytes32 projectLabelHash, bytes32 nameLabelHash)
        internal pure returns (bytes32)
    {
        bytes32 projectNodeHash = keccak256(abi.encodePacked(ETN_NODE, projectLabelHash));
        return keccak256(abi.encodePacked(projectNodeHash, nameLabelHash));
    }

    /**
     * @notice Generic namehash — split a dot-separated name off-chain and
     *         feed label hashes in reverse order (root last).
     */
    function namehash(bytes32[] memory labels) internal pure returns (bytes32 node) {
        node = bytes32(0);
        for (uint256 i = labels.length; i > 0; i--) {
            node = keccak256(abi.encodePacked(node, labels[i - 1]));
        }
    }
}
